const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[n]}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const today=()=>new Date().toISOString().slice(0,10);
// Levels come from each word's lv (1-4); words.json is ordered by level, so steps go 基本 → 上級.
// Guide (not shown in the UI): 基本≈中学1年, 初級≈中学3年, 中級≈高校, 上級≈大学以上.
const LEVELS=[['基本'],['初級'],['中級'],['上級']];
const levelOf=w=>Math.min(Math.max((w.lv||1)-1,0),3);
const nf=x=>Number(x).toLocaleString('ja-JP');
const ring=(d,n)=>{const p=n?Math.round(d/n*100):0,c=2*Math.PI*20;return `<span class="ring" aria-label="${p}%"><svg viewBox="0 0 48 48"><circle cx="24" cy="24" r="20"/><circle cx="24" cy="24" r="20" class="fg" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-p/100)}"/></svg><b>${p}%</b></span>`};
let wdeck='main',glv=-1,W=[],P=[],G=[],R={},wmode='list',wpos='',wsort='order',curTheme='',gameTimer=null,WMAP=null,dq='',dshown=50,back='words',byId=new Map(),lv=-1,shown=200,view='home',cur=null,sess=null,query='',theme='',ptheme='',favTab='w',loadState='loading';
// ---- state ----
const fresh=()=>({rec:{},gram:{},games:{speed:0},stepSize:10,autoplay:true,today:{date:'',steps:0},streak:{last:'',days:0},perDay:1,rate:0.9});
let S=fresh();
function load(){try{const v=JSON.parse(localStorage.getItem(KEY)||'{}');S={...fresh(),...sanitize(v)}}catch{S=fresh()}}
function sanitize(v){const out=fresh();if(!v||typeof v!=='object')return out;for(const [id,r] of Object.entries(v.rec||{})){if(!/^e[np]-\d{3,5}$/.test(id)||!r||typeof r!=='object')continue;const n=x=>Math.max(0,Math.floor(Number(x)||0));out.rec[id]={seen:n(r.seen),stage:Math.min(6,n(r.stage)),due:n(r.due),fav:!!r.fav,rev:!!r.rev,ok:n(r.ok),ng:n(r.ng)}}
 if(v.today&&/^\d{4}-\d\d-\d\d$/.test(v.today.date))out.today={date:v.today.date,steps:Math.min(99,Math.max(0,Number(v.today.steps)||0))};if(v.streak&&/^\d{4}-\d\d-\d\d$/.test(v.streak.last))out.streak={last:v.streak.last,days:Math.max(0,Number(v.streak.days)||0)};for(const [id,g] of Object.entries(v.gram||{})){if(/^g\d{2}$/.test(id)&&g&&typeof g==='object')out.gram[id]={best:Math.min(5,Math.max(0,Math.floor(Number(g.best)||0))),tries:Math.max(0,Math.floor(Number(g.tries)||0)),miss:Array.isArray(g.miss)?[...new Set(g.miss.filter(k=>Number.isInteger(k)&&k>=0&&k<10))]:[]}}if([1,2,3].includes(v.perDay))out.perDay=v.perDay;if([5,10,20].includes(v.stepSize))out.stepSize=v.stepSize;if(typeof v.autoplay==='boolean')out.autoplay=v.autoplay;if(v.games&&typeof v.games==='object')out.games={speed:Math.min(99999,Math.max(0,Math.floor(Number(v.games.speed)||0)))};if([0.7,0.8,0.9,1].includes(v.rate))out.rate=v.rate;return out}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch{}}
const rec=id=>S.rec[id]||{seen:0,stage:0,due:0,fav:false,rev:false,ok:0,ng:0};
const setRec=(id,f)=>{S.rec[id]={...rec(id),...f};save()};
const isDue=id=>{const r=rec(id);return r.seen>0&&((r.due&&r.due<=Date.now())||r.rev)};
const stepsToday=()=>S.today.date===today()?S.today.steps:0;
// ---- audio ----
let voices=[];function loadVoices(){if('speechSynthesis'in window)voices=speechSynthesis.getVoices()}
if('speechSynthesis'in window){loadVoices();speechSynthesis.onvoiceschanged=loadVoices}
function speak(t){if(!('speechSynthesis'in window)){toast('このブラウザは音声再生に対応していません');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-US';u.rate=S.rate;const v=voices.find(v=>v.lang==='en-US')||voices.find(v=>/^en/.test(v.lang));if(v)u.voice=v;speechSynthesis.speak(u)}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),1800)}
const audioBtn=(text,label='発音')=>`<button class="icon" onclick="speak(${esc(JSON.stringify(text))})" aria-label="${label}">${icon('audio')}</button>`;
const starBtn=id=>`<button class="icon star${rec(id).fav?' on':''}" onclick="toggleFav('${id}')" aria-pressed="${rec(id).fav}" aria-label="お気に入り">${icon('star')}</button>`;
function toggleFav(id){setRec(id,{fav:!rec(id).fav});render()}
// 復習登録: puts a word in the review queue now (separate from ☆). Cleared when answered right in review.
const revBtn=id=>`<button class="rev-btn${rec(id).rev?' on':''}" onclick="toggleRev('${id}')" aria-pressed="${rec(id).rev}">${icon('review')}<span>復習</span></button>`;
function toggleRev(id){const r=rec(id);if(r.rev)setRec(id,{rev:false});else setRec(id,{rev:true,seen:Math.max(1,r.seen),due:Date.now()});toast(rec(id).rev?'復習に登録しました':'復習の登録を外しました');render()}
// ---- navigation ----
function go(v){stopGame();view=v;cur=null;sess=null;render();window.scrollTo(0,0)}
function openWord(id,from){if(from)back=from;else if(view!=='word')back=view==='dict'?'dict':'words';cur=id;view='word';render();window.scrollTo(0,0)}
function nav(){const due=W.filter(w=>isDue(w.id)).length;const items=[['home','ホーム','home'],['words','単語','book'],['phrases','フレーズ','chat'],['grammar','文法','grid'],['review','復習','review'],['favorites','お気に入り','star']];
 $('#tabs').innerHTML=items.map(([v,t,i])=>`<button aria-current="${view===v||(v==='words'&&(view==='theme'||view==='word'&&back!=='dict'))||(v==='grammar'&&view==='lesson')?'page':'false'}" onclick="go('${v}')">${icon(i)}${v==='review'&&due?`<span class="num">${due}</span>`:''}<span>${t}</span></button>`).join('')}
function render(){nav();$('#main').innerHTML=loadState!=='ready'?(loadState==='error'?'<div class="empty">読み込めませんでした。通信を確認して再読み込みしてください。</div>':'<div class="empty">読み込んでいます…</div>'):sess?({gram:gramView,card:cardView,game:gameView}[sess.kind]||sessionView)():({home,dict,words,theme:themeView,word:wordDetail,grammar,lesson,phrases,review,favorites,settings}[view]||home)()}
// ---- home ----
const mainW=()=>W.filter(w=>w.theme!=='casual'),deckW=()=>wdeck==='casual'?W.filter(w=>w.theme==='casual'):mainW();
function nextWords(pool=mainW()){return pool.filter(w=>!(rec(w.id).seen>0)).slice(0,S.stepSize)}
function home(){const M=mainW(),learned=M.filter(w=>rec(w.id).seen>0).length,t=stepsToday();
 const gdone=G.filter(g=>gram(g.id).best>=g.quiz.length),gnext=G.find(g=>gram(g.id).best<g.quiz.length),pseen=P.filter(p=>rec(p.id).seen>0||rec(p.id).fav).length,pnext=P.find(p=>!(rec(p.id).seen>0));
 return dictBox('home')+`<section class="card h-rows" aria-label="学習">
 <div class="h-row"><button class="h-main" onclick="go('words')">${ring(learned,M.length)}<span class="h-text"><b>単語</b><small>${nf(learned)} / ${nf(M.length)}語 · 今日 ${t}/${S.perDay}ステップ</small></span>${icon('chev')}</button>
 <div class="lv-chips">${LEVELS.map(([n],k)=>{const c=M.filter(w=>levelOf(w)===k).length;return c?`<button onclick="wdeck='main';lv=${k};theme='';shown=200;go('words')"><b>${n}</b><small>${nf(c)}語</small></button>`:''}).join('')}<button class="on" onclick="wdeck='main';lv=-1;theme='';shown=200;go('words')"><b>全部</b><small>${nf(M.length)}語</small></button></div></div>
 <div class="h-row"><button class="h-main" onclick="go('phrases')">${ring(pseen,P.length)}<span class="h-text"><b>フレーズ</b><small>${pnext?`次 · ${esc(pnext.en)}`:`${nf(P.length)}表現`}</small></span>${icon('chev')}</button></div>
 <div class="h-row"><button class="h-main" onclick="${gnext?`openLesson('${gnext.id}')`:`go('grammar')`}">${ring(gdone.length,G.length)}<span class="h-text"><b>文法</b><small>${gnext?`次 · ${String(G.indexOf(gnext)+1).padStart(2,'0')} ${esc(gnext.title)}`:`全${G.length}課 履修済み`}</small></span>${icon('chev')}</button></div>
 <div class="h-row"><button class="h-main" onclick="go('review')"><span class="ring cnt"><svg viewBox="0 0 48 48"><circle cx="24" cy="24" r="20"/></svg><b><i>${W.filter(w=>isDue(w.id)).length}</i></b></span><span class="h-text"><b>復習</b><small>${W.filter(w=>isDue(w.id)).length?`今日の復習 ${nf(W.filter(w=>isDue(w.id)).length)}語`:'スピードゲーム・間違えた語'}</small></span>${icon('chev')}</button></div>
 </section>`}
function todayCard(){const M=mainW(),learned=M.filter(w=>rec(w.id).seen>0).length,next=nextWords(),due=M.filter(w=>isDue(w.id)).length,t=stepsToday(),met=t>=S.perDay,pct=Math.round(learned/M.length*100),stepNo=Math.floor(learned/S.stepSize)+1;
 return `<section class="card"><div class="daily-head"><h2 style="margin:0">今日の学習</h2>${met?'<span class="badge">✓ 今日の分は完了</span>':`<span class="muted">${t} / ${S.perDay}ステップ</span>`}</div>
 ${next.length||due?`<div class="tasks"><div class="task${due?'':' zero'}"><b>${Math.min(due,10)}</b><span>復習する語</span></div><div class="task${next.length?'':' zero'}"><b>${next.length}</b><span>新しい語</span></div></div>
 <button class="btn wide" onclick="startStep()">${met?'もう1ステップ進める →':'今日の学習をはじめる →'}</button>`:`<p><b>${nf(M.length)}語をすべて学習しました。</b>復習で定着させましょう。</p>`}
 <div class="meta"><span>ステップ ${stepNo}${S.streak.days&&S.streak.last>=yesterday()?` · 連続${S.streak.days}日`:''}</span><span>すべて ${nf(learned)} / ${nf(M.length)}語</span></div><div class="bar"><i style="width:${pct}%"></i></div>
 <details class="mini-set"><summary>設定</summary><div class="settings">${stepSettings()}</div></details></section>`}
function stepSettings(){return `<label>1日のステップ数<select onchange="S.perDay=Number(this.value);save();render()">${[1,2,3].map(n=>`<option ${S.perDay===n?'selected':''}>${n}</option>`).join('')}</select></label><label>1ステップの語数<select onchange="S.stepSize=Number(this.value);save();render()">${[5,10,20].map(n=>`<option value="${n}" ${S.stepSize===n?'selected':''}>${n}語</option>`).join('')}</select></label><label>自動で発音<select onchange="S.autoplay=this.value==='1';save()"><option value="1" ${S.autoplay?'selected':''}>する</option><option value="0" ${S.autoplay?'':'selected'}>しない</option></select></label>`}
const yesterday=()=>new Date(Date.now()-86400000).toISOString().slice(0,10);
// ---- words ----
const fold=s=>String(s).toLowerCase();
function wordList(){const q=fold(query.trim()),xs=deckW().filter(w=>(lv<0||levelOf(w)===lv)&&(!wpos||w.pos===wpos)&&(!theme||w.theme===theme)&&(!q||fold(w.w).includes(q)||w.ja.includes(query.trim())));return wsort==='abc'?[...xs].sort((a,b)=>a.w.localeCompare(b.w,'en',{sensitivity:'base'})):wsort==='new'?[...xs.filter(w=>!(rec(w.id).seen>0)),...xs.filter(w=>rec(w.id).seen>0)]:xs}
const POS_LIST=['名詞','動詞','形容詞','副詞','前置詞','接続詞','代名詞','限定詞','助動詞','疑問詞','間投詞'];
function words(){const D=deckW(),xs=wordList(),themes=themeKeys().filter(t=>t!=='casual');
 const lvchips=`<section class="card lv-grid">${LEVELS.map(([n],k)=>{const c=D.filter(w=>levelOf(w)===k).length;return c?`<button aria-pressed="${lv===k}" onclick="lv=${k};shown=200;render()"><b>${n}</b> <small>${nf(c)}語</small></button>`:''}).join('')}<button aria-pressed="${lv<0}" onclick="lv=-1;shown=200;render()"><b>全部</b> <small>${nf(D.length)}語</small></button></section>`;
 return `<h1>単語</h1>${wdeck==='main'?todayCard():''}
 <div class="seg deck" role="tablist"><button role="tab" aria-selected="${wdeck==='main'}" onclick="wdeck='main';lv=-1;theme='';shown=200;render()">単語</button><button role="tab" aria-selected="${wdeck==='casual'}" onclick="wdeck='casual';lv=-1;theme='';shown=200;render()">口語・ネット</button></div>
 ${lvchips}
 ${wdeck==='main'?`<div class="sec-head"><h2>テーマで学ぶ</h2><span class="muted">すべて · ${themes.length}テーマ</span></div>${themeTiles(themes)}`:`<p class="muted note">会話・SNSで使うくだけた語です。改まった場面では使わないものもあります。</p>`}
 <section class="card filters"><label class="f-sort"><select onchange="wsort=this.value;shown=200;render()" aria-label="並べ替え">${[['order','並び：学ぶ順'],['abc','並び：ABC順'],['new','並び：未学習を先に']].map(([v,t])=>`<option value="${v}" ${wsort===v?'selected':''}>${t}</option>`).join('')}</select></label><label><select onchange="wpos=this.value;shown=200;render()" aria-label="品詞"><option value="">品詞：すべて</option>${POS_LIST.map(x=>`<option value="${x}" ${wpos===x?'selected':''}>品詞：${x}</option>`).join('')}</select></label><input class="search" type="search" placeholder="一覧を絞り込む（英語・日本語）" value="${esc(query)}" oninput="query=this.value;shown=200;document.getElementById('wl').innerHTML=wordRows();document.getElementById('wcount').textContent=wordList().length.toLocaleString('ja-JP')">${theme?`<button class="chip on" onclick="theme='';shown=200;render()">テーマ：${esc(THEMES[theme]||theme)} ✕</button>`:''}</section>
 <section class="card practice"><div class="sec-head"><h2>一覧から練習</h2><span class="muted">10語ずつ</span></div><div class="pr-grid"><button class="pr dark" onclick="startCards(wordList())"><b>カード</b><small>めくって自分で確認<br>思い出せない語はもう一度</small></button><button class="pr" onclick="startQuiz('w',wordList(),'mix',true)"><b>テスト</b><small>4択で確認<br>英→日・日→英・聞き取り</small></button></div></section>
 <p class="list-cap">表示 <b id="wcount">${nf(xs.length)}</b>語 · ${lv<0?'すべて':LEVELS[lv][0]}${wpos?' · '+wpos:''}</p>
 <ul class="list wl" id="wl">${wordRows()}</ul>`}
const wItem=(w,from)=>`<li class="w-item">${rec(w.id).seen?'<span class="seen-dot" title="学習済み"></span>':''}<button class="item" onclick="openWord('${w.id}'${from?`,'${from}'`:''})"><span class="w-head"><b>${esc(w.w)}</b><span class="ipa">/${esc(w.ipa)}/</span></span><span class="w-ja">${esc(w.ja)}</span><span class="tags"><span class="lv lv${levelOf(w)+1}">${LEVELS[levelOf(w)][0]}</span><span class="tag">${esc(w.pos)}</span><span class="t-theme">${esc(THEMES[w.theme]||w.theme)}</span></span></button><span class="w-acts">${audioBtn(w.w).replace('class="icon"','class="icon round"')}${starBtn(w.id)}<button class="icon rev-ico${rec(w.id).rev?' on':''}" onclick="toggleRev('${w.id}')" aria-pressed="${rec(w.id).rev}" aria-label="復習に登録">${icon('review')}</button></span></li>`;
