function wordDetail(){const w=byId.get(cur);if(!w)return words();const i=W.indexOf(w);
 return `<button class="back-link" onclick="go(back==='dict'?'dict':'words')">← ${back==='dict'?'辞書に戻る':'単語に戻る'}</button><section class="card"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px"><div><p class="word-big">${esc(w.w)}</p><span class="ipa-big">/${esc(w.ipa)}/</span> <span class="pos">${esc(w.pos)}</span></div><div class="row-actions">${audioBtn(w.w)}${starBtn(w.id)}</div></div>
 <p class="ja-big">${esc(w.ja)}</p><div class="ex"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><p class="en">${exWords(w.ex,'open',w.id)}</p>${audioBtn(w.ex,'例文を再生')}</div><p>${esc(w.exJa)}</p></div>
 <p class="muted"><span class="lv">${LEVELS[levelOf(w)][0]}</span> ${i+1}語目 · <button class="linkish" onclick="openTheme('${w.theme}')">${THEMES[w.theme]||w.theme}</button></p><div class="row-actions" style="margin-top:8px">${revBtn(w.id)}</div><p class="muted small">例文の単語を押すと、その単語のページを開きます。</p></section>
 <div class="row-actions">${i>0?`<button class="btn light" onclick="openWord('${W[i-1].id}')">← ${esc(W[i-1].w)}</button>`:''}${i<W.length-1?`<button class="btn light" onclick="openWord('${W[i+1].id}')">${esc(W[i+1].w)} →</button>`:''}</div>`}
// ---- dictionary ----
// Searches every word and phrase regardless of level/theme filters: English (with -s/-ed/-ing and common
// irregular forms), Japanese (kanji/kana), and hiragana readings of the Japanese (data/ja-readings.json).
const HKEY='english-steps-dict-history';
const IRREG={went:'go',gone:'go',saw:'see',seen:'see',took:'take',taken:'take',made:'make',got:'get',gotten:'get',gave:'give',given:'give',came:'come',ate:'eat',eaten:'eat',drank:'drink',drunk:'drink',bought:'buy',thought:'think',told:'tell',said:'say',knew:'know',known:'know',found:'find',left:'leave',felt:'feel',kept:'keep',brought:'bring',began:'begin',begun:'begin',ran:'run',wrote:'write',written:'write',spoke:'speak',spoken:'speak',broke:'break',broken:'break',chose:'choose',chosen:'choose',fell:'fall',fallen:'fall',flew:'fly',flown:'fly',forgot:'forget',forgotten:'forget',won:'win',lost:'lose',paid:'pay',sold:'sell',sent:'send',spent:'spend',stood:'stand',understood:'understand',taught:'teach',caught:'catch',heard:'hear',held:'hold',meant:'mean',met:'meet',sat:'sit',slept:'sleep',built:'build',drove:'drive',driven:'drive',rode:'ride',ridden:'ride',swam:'swim',sang:'sing',sung:'sing',wore:'wear',worn:'wear',woke:'wake',threw:'throw',thrown:'throw',grew:'grow',grown:'grow',drew:'draw',drawn:'draw',hid:'hide',led:'lead',lent:'lend',fought:'fight',taught:'teach',was:'be',were:'be',been:'be',is:'be',are:'be',am:'be',has:'have',had:'have',did:'do',done:'do',does:'do',children:'child',men:'man',women:'woman',people:'person',feet:'foot',teeth:'tooth',mice:'mouse',better:'good',best:'good',worse:'bad',worst:'bad'};
const toHira=s=>String(s).replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));
const normQ=s=>String(s).normalize('NFKC').trim().toLowerCase();
const jaParts=s=>String(s).replace(/（[^）]*）|\([^)]*\)/g,'').split(/[・、,，]/).map(x=>x.trim()).filter(Boolean);
function enBases(q){const out=new Set([q]);if(IRREG[q])out.add(IRREG[q]);const add=x=>x.length>1&&out.add(x);
 if(q.endsWith('ies'))add(q.slice(0,-3)+'y');if(q.endsWith('es'))add(q.slice(0,-2));if(q.endsWith('s'))add(q.slice(0,-1));
 if(q.endsWith('ied'))add(q.slice(0,-3)+'y');if(q.endsWith('ed')){add(q.slice(0,-2));add(q.slice(0,-1));if(/(.)\1ed$/.test(q))add(q.slice(0,-3))}
 if(q.endsWith('ing')){add(q.slice(0,-3));add(q.slice(0,-3)+'e');if(/(.)\1ing$/.test(q))add(q.slice(0,-4))}
 if(q.endsWith('er')){add(q.slice(0,-2));add(q.slice(0,-1))}if(q.endsWith('est')){add(q.slice(0,-3));add(q.slice(0,-2))}return out}
function dictScore(x,q){const latin=/^[a-z0-9 '\-.]+$/.test(q);let best=Infinity;const b=v=>{if(v<best)best=v};
 if(latin){const h=(x.w||x.en).toLowerCase(),bases=enBases(q);const qt=q.split(/\s+/),ht=h.split(/\s+/);if(h===q)b(0);else if(bases.has(h)||(qt.length>1&&qt.length===ht.length&&qt.every((t,k)=>t===ht[k]||enBases(t).has(ht[k]))))b(1);else if(h.startsWith(q))b(q.length>=3?2:3);else if(q.length>=3&&h.split(/[ \-]/).some(t=>t===q||bases.has(t)))b(3);else if(q.length>=3&&h.includes(q))b(5);
  if(best>6&&q.length>=3&&x.ex&&new RegExp('\\b'+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(x.ex))b(8)}
 else{const hq=toHira(q),parts=jaParts(x.ja),rd=R[x.id]||'',rparts=rd?jaParts(rd):[];
  if(parts.includes(q)||parts.some(p=>toHira(p)===hq)||rparts.includes(hq))b(0);
  else if(parts.some(p=>p.startsWith(q)||toHira(p).startsWith(hq))||rparts.some(p=>p.startsWith(hq)))b(2);
  else if(x.ja.includes(q)||toHira(x.ja).includes(hq))b(4);else if(hq.length>=2&&rd.includes(hq))b(5)}
 return best}
function dictResults(raw){const q=normQ(raw);if(!q)return {w:[],p:[]};const rank=xs=>xs.map((x,i)=>({x,i,s:dictScore(x,q)})).filter(r=>r.s<Infinity).sort((a,b)=>a.s-b.s||(a.x.lv||0)-(b.x.lv||0)||a.i-b.i).map(r=>r.x);return {w:rank(W),p:rank(P)}}
function dictHistory(){try{const h=JSON.parse(localStorage.getItem(HKEY)||'[]');return Array.isArray(h)?h.filter(x=>typeof x==='string').slice(0,8):[]}catch{return[]}}
function addHistory(q){q=String(q).trim();if(!q)return;const h=[q,...dictHistory().filter(x=>x!==q)].slice(0,8);try{localStorage.setItem(HKEY,JSON.stringify(h))}catch{}}
function clearHistory(){try{localStorage.removeItem(HKEY)}catch{}render()}
function searchDict(q){dq=String(q||'');dshown=50;addHistory(dq);if(view!=='dict')go('dict');else render()}
function dictBox(where){const h=dictHistory(),chips=h.length?`<div class="d-try"><span>最近の検索</span>${h.map(q=>`<button type="button" data-q="${esc(q)}" onclick="searchDict(this.dataset.q)">${esc(q)}</button>`).join('')}<button type="button" class="d-clear" onclick="clearHistory()">消去</button></div>`:`<div class="d-try"><span>例</span>${['食べる','たべる','ホテル','went','beautiful','約束'].map(q=>`<button type="button" onclick="searchDict(this.textContent)">${esc(q)}</button>`).join('')}</div>`;
 return `<section class="${where==='home'?'card ':''}d-box" aria-label="辞書">${where==='home'?`<h2 class="d-title"><span class="d-mark">${icon('search')}</span>英語辞書</h2>`:''}<form class="d-form" role="search" onsubmit="event.preventDefault();searchDict(this.q.value)"><span class="d-icon" aria-hidden="true">${icon('search')}</span><input name="q" type="search" enterkeyhint="search" autocomplete="off" placeholder="英語・日本語・ひらがなで検索" aria-label="英語辞書" value="${where==='dict'?esc(dq):''}" ${where==='dict'?`oninput="dq=this.value;dshown=50;document.getElementById('dres').innerHTML=dictRows()"`:''}><button class="btn" type="submit">検索</button></form>${chips}</section>`}
const wordRow=w=>wItem(w,'dict');
function dictRows(){const q=dq.trim();if(!q)return '<p class="muted">英単語・日本語の意味・ひらがなの読みで、全レベルの単語とフレーズを探せます。</p>';const r=dictResults(q),n=r.w.length+r.p.length;
 if(!n)return `<p class="d-cap">「${esc(q)}」は見つかりませんでした。</p>`;
 return `<p class="d-cap">辞書 · 「${esc(q)}」 ${n}件</p>${r.w.length?`<ul class="list">${r.w.slice(0,dshown).map(wordRow).join('')}${r.w.length>dshown?`<li class="more"><button class="btn light wide" onclick="dshown+=50;document.getElementById('dres').innerHTML=dictRows()">もっと見る（残り${r.w.length-dshown}語）</button></li>`:''}</ul>`:''}
 ${r.p.length?`<h2 class="g-level">フレーズ</h2><ul class="list">${r.p.slice(0,20).map(p=>`<li><button class="item" onclick="speak(${esc(JSON.stringify(p.en))})"><b>${esc(p.en)}</b><small>${esc(p.ja)}</small></button>${audioBtn(p.en)}${starBtn(p.id)}</li>`).join('')}</ul>`:''}`}
function dict(){return `<h1>辞書</h1>${dictBox('dict')}<div id="dres">${dictRows()}</div>`}
// ---- example words ----
// Each English word in an example is a button: on a word page it opens that word, in a session it speaks.
function wordIndex(){if(!WMAP){WMAP=new Map();for(const w of W){const k=w.w.toLowerCase();if(!WMAP.has(k))WMAP.set(k,w)}}return WMAP}
function lookupToken(t){const q=t.toLowerCase().replace(/['’]s$/,''),m=wordIndex();if(m.has(q))return m.get(q);for(const b of enBases(q))if(m.has(b))return m.get(b);return null}
function exWords(sentence,mode,selfId){return String(sentence).split(/([A-Za-z][A-Za-z'’\-]*)/).map((t,k)=>{if(k%2===0)return esc(t);const w=lookupToken(t);if(!w)return esc(t);const self=w.id===selfId;return `<button class="exw${self?' self':''}" onclick="${mode==='open'&&!self?`openWord('${w.id}')`:`speak(${esc(JSON.stringify(t))})`}" title="${esc(w.w+'：'+w.ja)}">${esc(t)}</button>`}).join('')}
// ---- themes ----
const TICON={people:'<circle cx="12" cy="8" r="3.5"/><path d="M5 20c1-4 4-6 7-6s6 2 7 6"/>',greetings:'<path d="M4 6h16v10H10l-5 4z"/><path d="M9 11h.01M15 11h.01"/>',food:'<path d="M5 3v8a2 2 0 0 0 4 0V3M7 11v10"/><path d="M17 3c-2 0-3 3-3 6s1 4 3 4v8"/>',animals:'<circle cx="7" cy="9" r="2"/><circle cx="17" cy="9" r="2"/><circle cx="10" cy="5" r="1.6"/><circle cx="14" cy="5" r="1.6"/><path d="M8 18c0-3 2-5 4-5s4 2 4 5-2 2-4 2-4 1-4-2z"/>',body:'<circle cx="12" cy="5" r="2.5"/><path d="M12 8v7M7 11h10M9 21l3-6 3 6"/>',places:'<path d="M12 21s7-6 7-12a7 7 0 0 0-14 0c0 6 7 12 7 12z"/><circle cx="12" cy="9" r="2.5"/>',home:'<path d="M3 11l9-7 9 7v9H3z"/><path d="M10 20v-5h4v5"/>',time:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>',weather:'<circle cx="8" cy="8" r="3"/><path d="M8 2v1M2 8h1M3.8 3.8l.7.7"/><path d="M9 19h9a3 3 0 0 0 0-6 5 5 0 0 0-9.6 1.4A2.5 2.5 0 0 0 9 19z"/>',transport:'<rect x="4" y="4" width="16" height="12" rx="2"/><path d="M4 11h16M7 20l2-4M17 20l-2-4"/><circle cx="8" cy="13.5" r=".5"/><circle cx="16" cy="13.5" r=".5"/>',money:'<rect x="3" y="6" width="18" height="12" rx="2"/><circle cx="12" cy="12" r="2.5"/>',actions:'<circle cx="13" cy="4" r="2"/><path d="M8 21l3-6 3 2v5M11 15l1-6 4 3h3M12 9l-4 2-2 3"/>',feelings:'<circle cx="12" cy="12" r="8"/><path d="M8.5 14c1 1.5 2.2 2 3.5 2s2.5-.5 3.5-2"/><path d="M9 9.5h.01M15 9.5h.01"/>',description:'<path d="M4 20l4-1 11-11-3-3L5 16z"/><path d="M14 7l3 3"/>',grammar:'<path d="M4 6h10M4 12h16M4 18h12"/>',basics:'<path d="M12 3l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 16.4 6.8 19.1l1-5.8L3.5 9.2l5.9-.9z"/>',numbers:'<path d="M9 4L7 20M17 4l-2 16M4 9h16M3 15h16"/>',colors:'<path d="M12 3a9 9 0 1 0 0 18c1.5 0 2-1 2-2s-1-1.5-1-2.5 1-1.5 2-1.5h2a4 4 0 0 0 4-4c0-4.5-4-8-9-8z"/><circle cx="7.5" cy="11" r="1"/><circle cx="10" cy="7" r="1"/><circle cx="15" cy="7.5" r="1"/>',work:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M9 7V5h6v2M3 13h18"/>',nature:'<path d="M12 21V11"/><path d="M12 11c-4 0-6-3-6-7 4 0 6 3 6 7zM12 14c3 0 5-2 5-6-3 0-5 2-5 6z"/>',shopping:'<path d="M5 8h14l-1 12H6z"/><path d="M9 8a3 3 0 0 1 6 0"/>',smalltalk:'<path d="M3 5h11v7H7l-4 3z"/><path d="M10 15h7l4 3v-8h-4"/>',clothes:'<path d="M8 4l4 2 4-2 4 4-3 3v9H7v-9L4 8z"/>',school:'<path d="M2 9l10-5 10 5-10 5z"/><path d="M6 11v5c2 2 10 2 12 0v-5"/>',hobbies:'<circle cx="7" cy="17" r="3"/><circle cx="17" cy="15" r="3"/><path d="M10 17V5l10-2v12"/>',society:'<path d="M3 10l9-6 9 6M5 10v8M9 10v8M15 10v8M19 10v8M3 20h18"/>',health:'<path d="M12 20s-8-4.5-8-10a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 5.5-8 10-8 10z"/><path d="M12 9v5M9.5 11.5h5"/>',technology:'<rect x="6" y="3" width="12" height="18" rx="2"/><path d="M11 18h2"/>',casual:'<path d="M4 5h16v11H9l-5 4z"/><path d="M8 10h.01M12 10h.01M16 10h.01"/>'};
const themeKeys=()=>{const have=new Set(W.map(w=>w.theme));return Object.keys(THEMES).filter(t=>have.has(t)).concat([...have].filter(t=>!(t in THEMES)))};
const themeWords=t=>W.filter(w=>w.theme===t);
const ticon=t=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${TICON[t]||ICON.words}</svg>`;
function themeTiles(keys=themeKeys()){return `<div class="tiles hscroll">${keys.map(t=>{const xs=themeWords(t),d=xs.filter(w=>rec(w.id).seen>0).length;return `<button class="tile${d===xs.length?' done':''}" onclick="openTheme('${t}')"><span class="t-ico">${ticon(t)}</span><b>${esc(THEMES[t]||t)}</b><small>${d} / ${xs.length}</small><span class="bar"><i style="width:${Math.round(d/xs.length*100)}%"></i></span></button>`}).join('')}</div>`}
function openTheme(t){stopGame();curTheme=t;sess=null;view='theme';render();window.scrollTo(0,0)}
function themeView(){const t=curTheme,xs=themeWords(t);if(!xs.length)return words();const d=xs.filter(w=>rec(w.id).seen>0).length,next=nextWords(xs),due=xs.filter(w=>isDue(w.id)).length,seen=xs.filter(w=>rec(w.id).seen>0);
 return `<button class="back-link" onclick="go('words')">← 単語に戻る</button><section class="card"><div class="t-head">${ticon(t)}<div><h2 style="margin:0">${esc(THEMES[t]||t)}</h2><p class="muted" style="margin:2px 0 0">学習済み ${d} / ${xs.length}語${due?` · 復習 ${due}語`:''}</p></div></div><div class="bar"><i style="width:${Math.round(d/xs.length*100)}%"></i></div>
 ${next.length?`<p class="muted" style="margin-top:12px">次に覚える語：${next.slice(0,6).map(w=>esc(w.w)).join('、')}${next.length>6?' …':''}</p><button class="btn wide" onclick="startStep(themeWords(curTheme))">新しい語を覚える（${next.length}語） →</button>`:due?`<button class="btn wide" style="margin-top:12px" onclick="startStep(themeWords(curTheme))">復習する（${Math.min(due,10)}語） →</button>`:'<p style="margin-top:12px"><b>このテーマの語はすべて学習しました。</b></p>'}</section>
 <div class="row-actions"><button class="btn light" onclick="startCards(${seen.length>=4?'themeWords(curTheme).filter(w=>rec(w.id).seen>0)':'themeWords(curTheme)'})">カード</button><button class="btn light" onclick="startQuiz('w',themeWords(curTheme),'enja')">英→日 テスト</button><button class="btn light" onclick="startQuiz('w',themeWords(curTheme),'jaen')">日→英 テスト</button><button class="btn light" onclick="theme=curTheme;wdeck=curTheme==='casual'?'casual':'main';lv=-1;shown=200;go('words')">一覧で見る</button></div>`}
// ---- cards ----
// Flip cards: English first; the back shows the meaning and example. もう一度 puts the card back (up to twice).
function startCards(pool){const xs=shuffle(pool).slice(0,20);if(!xs.length){toast('カードにする語がありません');return}stopGame();sess={kind:'card',ids:xs.map(w=>w.id),i:0,flip:false,ok:0,again:{},missed:new Set()};render();window.scrollTo(0,0);if(S.autoplay)setTimeout(()=>speak(xs[0].w),200)}
function cardView(){const s=sess,n=s.ids.length;if(s.i>=n)return `<section class="card result"><p class="muted">カード</p><div class="score">${s.ok} / ${new Set(s.ids).size}</div><p>${s.missed.size?`思い出せなかった語が${s.missed.size}語あります。`:'すべて思い出せました！'}</p><div class="row-actions" style="justify-content:center">${s.missed.size>=2?`<button class="btn" onclick="startQuiz('w',[...sess.missed].map(id=>byId.get(id)),'enja',true)">その語でテスト</button>`:''}<button class="btn light" onclick="endSession()">戻る</button></div></section>`;
 const x=byId.get(s.ids[s.i]);
 return `<div class="sess-top"><button class="btn light" style="min-height:40px" onclick="endSession()">← 終了</button><span class="muted">${s.i+1} / ${n}</span></div><div class="progress"><i style="width:${s.i/n*100}%"></i></div>
 <section class="card flash${s.flip?' back':''}"><div style="display:flex;justify-content:space-between;gap:8px"><div><p class="word-big">${esc(x.w)}</p><span class="ipa-big">/${esc(x.ipa)}/</span></div>${audioBtn(x.w)}</div>
 ${s.flip?`<p class="ja-big">${esc(x.ja)} <span class="pos">${esc(x.pos)}</span></p><div class="ex"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><p class="en">${exWords(x.ex,'speak',x.id)}</p>${audioBtn(x.ex,'例文を再生')}</div><p>${esc(x.exJa)}</p></div><div class="row-actions" style="margin-top:8px">${revBtn(x.id)}${starBtn(x.id)}</div>`:'<p class="muted" style="margin-top:14px">意味を思い出してから、カードを裏返しましょう。</p>'}</section>
 ${s.flip?`<div class="next two"><button class="btn light" onclick="cardAns(false)">もう一度</button><button class="btn" onclick="cardAns(true)">思い出せた</button></div>`:`<button class="btn wide next" onclick="sess.flip=true;render()">答えを見る</button>`}`}
function cardAns(ok){const s=sess,id=s.ids[s.i],r=rec(id);setRec(id,{seen:Math.max(1,r.seen),ok:r.ok+(ok?1:0),ng:r.ng+(ok?0:1)});if(ok){if(!s.missed.has(id))s.ok++}else{s.missed.add(id);s.again[id]=(s.again[id]||0)+1;if(s.again[id]<=2)s.ids.push(id)}s.i++;s.flip=false;render();window.scrollTo(0,0);const nx=s.ids[s.i];if(nx&&S.autoplay)setTimeout(()=>speak(byId.get(nx).w),150)}
// ---- speed game ----
// 60 seconds of English→Japanese choices. Each right answer scores 10 × (1 + combo/5); a miss resets the combo.
function stopGame(){if(gameTimer){clearInterval(gameTimer);gameTimer=null}}
function startGame(){const learned=W.filter(w=>rec(w.id).seen>0),pool=learned.length>=20?learned:W.filter(w=>w.lv===1);stopGame();sess={kind:'game',pool,score:0,combo:0,maxCombo:0,ok:0,n:0,end:Date.now()+60000,q:null,flash:null,over:false};gameQ();render();window.scrollTo(0,0);if(typeof setInterval==='function')gameTimer=setInterval(gameTick,200)}
function gameQ(){const s=sess,x=s.pool[Math.floor(Math.random()*s.pool.length)],near=W.filter(y=>y.id!==x.id&&y.pos===x.pos&&y.ja!==x.ja&&Math.abs((y.lv||1)-(x.lv||1))<=1),others=shuffle(near.length>=3?near:W.filter(y=>y.id!==x.id&&y.ja!==x.ja)).slice(0,3);s.q={x,choices:shuffle([x,...others])}}
function gameTick(){const s=sess;if(!s||s.kind!=='game'){stopGame();return}const left=Math.max(0,s.end-Date.now());const bar=document.getElementById('gtime');if(bar)bar.style.width=(left/600)+'%';const sec=document.getElementById('gsec');if(sec)sec.textContent=Math.ceil(left/1000);if(!left)gameOver()}
function gameOver(){const s=sess;if(!s||s.over)return;s.over=true;stopGame();if(s.score>S.games.speed){s.record=true;S.games.speed=s.score;save()}render()}
function gameAnswer(k){const s=sess;if(!s||s.over||s.flash)return;const c=s.q.choices[k],ok=c.id===s.q.x.id;s.n++;if(ok){s.ok++;s.combo++;s.maxCombo=Math.max(s.maxCombo,s.combo);s.score+=10*(1+Math.floor((s.combo-1)/5))}else s.combo=0;s.flash={k,ok};render();setTimeout(()=>{if(sess!==s||s.over)return;s.flash=null;gameQ();render()},ok?250:900)}
function gameView(){const s=sess;if(s.over)return `<section class="card result"><p class="muted">スピードゲーム</p><div class="score">${s.score}点</div><p>${s.ok} / ${s.n}問正解 · 最大コンボ ${s.maxCombo}</p><p>${s.record?'<b>ベスト記録を更新しました！</b>':`ベスト ${S.games.speed}点`}</p><div class="row-actions" style="justify-content:center"><button class="btn" onclick="startGame()">もう一度</button><button class="btn light" onclick="sess=null;go('review')">戻る</button></div></section>`;
 const q=s.q,left=Math.max(0,s.end-Date.now());
 return `<div class="sess-top"><button class="btn light" style="min-height:40px" onclick="stopGame();sess=null;go('review')">← 終了</button><span class="g-stat"><b id="gsec">${Math.ceil(left/1000)}</b>秒 · ${s.score}点${s.combo>=2?` · <span class="combo">${s.combo}コンボ</span>`:''}</span></div><div class="progress"><i id="gtime" style="width:${left/600}%"></i></div>
 <section class="card"><div class="q-prompt"><div class="big">${esc(q.x.w)}</div><div class="sub">意味は？</div></div><div class="choices">${q.choices.map((c,k)=>`<button class="choice${s.flash?(c.id===q.x.id?' ok':k===s.flash.k?' ng':''):''}" onclick="gameAnswer(${k})">${esc(c.ja)}</button>`).join('')}</div></section>`}
// ---- grammar ----
const gram=id=>S.gram[id]||{best:0,tries:0,miss:[]};
const blank=q=>esc(q).replace('___','<span class="blank">＿＿＿</span>');
function grammar(){const done=G.filter(g=>gram(g.id).best>=g.quiz.length).length,lvs=LEVELS.map((l,k)=>k).filter(k=>G.some(g=>g.lv===k+1));
 return `<div class="page-head"><h1>文法</h1><span class="muted">${lvs.length}レベル · ${G.length}課 · 履修済み ${done}</span></div>
 <div class="chips"><button class="chip" aria-pressed="${glv<0}" onclick="glv=-1;render()">すべて</button>${lvs.map(k=>`<button class="chip" aria-pressed="${glv===k}" onclick="glv=${k};render()">${LEVELS[k][0]}</button>`).join('')}</div>
 <p class="muted note">練習問題を全問正解すると履修済みになります。</p>`+lvs.filter(k=>glv<0||glv===k).map(k=>{const xs=G.filter(g=>g.lv===k+1),d=xs.filter(g=>gram(g.id).best>=g.quiz.length).length;
 return `<div class="ch-head"><span class="ch-ico">${icon('grid')}</span><h2>${LEVELS[k][0]}</h2><span class="muted">${d} / ${xs.length}</span></div><ul class="lessons">${xs.map(g=>{const r=gram(g.id),pass=r.best>=g.quiz.length,no=String(G.indexOf(g)+1).padStart(2,'0');return `<li><button onclick="openLesson('${g.id}')"><span class="no${pass?' done':''}">${pass?'✓':no}</span><span class="l-text"><b>${esc(g.title)}</b><small>${esc(g.form)}</small></span>${icon('arrow')}</button></li>`}).join('')}</ul>`}).join('')}
function openLesson(id){cur=id;view='lesson';render();window.scrollTo(0,0)}
function lesson(){const g=G.find(x=>x.id===cur);if(!g)return grammar();const i=G.indexOf(g),r=gram(g.id),pass=r.best>=g.quiz.length,parts=g.form.split(' ／ ')[0].split(/\s*＋\s*/).filter(Boolean);
 return `<button class="back-link" onclick="go('grammar')">← 文法に戻る</button><p class="eyebrow">LESSON ${String(i+1).padStart(2,'0')} / ${G.length} · ${LEVELS[g.lv-1][0]}${pass?' · ✓ 履修済み':''}</p><h1 class="l-title">${esc(g.title)}</h1>
 <section class="card soft"><p class="eyebrow">文の組み立て</p><p class="form-big">${esc(g.form)}</p><div class="roles">${parts.map((x,k)=>`<span class="role r${k%4}">${esc(x)}</span>`).join('')}</div></section>
 <section class="card"><p class="eyebrow">01 / 理解する</p><h2>しくみをつかむ</h2><p>${esc(g.point)}</p>${g.tips&&g.tips.length?`<ul class="tips">${g.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}</section>
 <section class="card"><p class="eyebrow">02 / 例文</p><h2>例文で確かめる</h2>${g.ex.map(e=>`<div class="ex"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><p class="en">${exWords(e.en,'open')}</p>${audioBtn(e.en,'例文を再生')}</div><p>${esc(e.ja)}</p></div>`).join('')}</section>
 <section class="card"><p class="eyebrow">03 / 練習</p><h2>練習問題</h2><p class="muted">${g.quiz.length}問。全問正解で履修済みになります。${r.tries?`最高 ${r.best}/${g.quiz.length}。`:''}</p>${r.miss&&r.miss.length?`<button class="btn light wide" style="margin-bottom:8px" onclick="startGram('${g.id}',true)">間違えた問題をやり直す（${r.miss.length}問）</button>`:''}</section>
 <button class="btn wide next" onclick="startGram('${g.id}')">練習問題をはじめる →</button>
 <div class="row-actions" style="margin-top:10px">${i>0?`<button class="btn light" onclick="openLesson('${G[i-1].id}')">← 前の課</button>`:''}${i<G.length-1?`<button class="btn light" onclick="openLesson('${G[i+1].id}')">次の課 →</button>`:''}</div>`}
function startGram(id,onlyMissed){const g=G.find(x=>x.id===id);if(!g)return;const miss=gram(id).miss||[],qs=g.quiz.map((q,k)=>({...q,k})).filter(q=>!onlyMissed||miss.includes(q.k));if(!qs.length)return;sess={kind:'gram',lid:id,full:!onlyMissed,qs:shuffle(qs).map(q=>({...q,order:shuffle([0,1,2,3])})),i:0,ok:0,total:0,answered:null,missed:[]};render();window.scrollTo(0,0)}
function gramView(){const s=sess,n=s.qs.length,g=G.find(x=>x.id===s.lid);
 if(s.i>=n){const pass=s.ok>=n-1;return `<section class="card result"><p class="muted">${esc(g.title)}</p><div class="score">${s.ok} / ${n}</div><p>${s.ok===n?(s.full?'全問正解です！この課は履修済みです。':'全問正解です！'):pass?'あと少しです。間違えた問題を見直しましょう。':'例文を読み直して、もう一度挑戦しましょう。'}</p><div class="row-actions" style="justify-content:center">${s.missed.length?`<button class="btn" onclick="startGram('${s.lid}',true)">間違えた問題だけ</button>`:''}<button class="btn${s.missed.length?' light':''}" onclick="startGram('${s.lid}')">もう一度</button><button class="btn light" onclick="sess=null;openLesson('${s.lid}')">課に戻る</button></div></section>`}
 const q=s.qs[s.i],done=s.answered!==null,full=q.q.replace('___',q.choices[q.a]);
 return `<div class="sess-top"><button class="btn light" style="min-height:40px" onclick="sess=null;openLesson('${s.lid}')">← 終了</button><span class="muted">${s.i+1} / ${n}</span></div><div class="progress"><i style="width:${s.i/n*100}%"></i></div>
 <section class="card"><p class="muted">${esc(g.title)}</p><div class="q-prompt"><div class="big" style="font-size:1.25rem;line-height:1.5">${blank(q.q)}</div><div class="sub">${esc(q.ja)}</div></div>
 <div class="choices">${q.order.map(k=>`<button class="choice${done?(k===q.a?' ok':k===s.answered?' ng':''):''}" ${done?'disabled':''} onclick="gramAnswer(${k})">${esc(q.choices[k])}</button>`).join('')}</div>
 ${done?`<div class="ex" style="margin-top:12px"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><p class="en">${esc(full)}</p>${audioBtn(full,'例文を再生')}</div><p>${esc(q.why)}</p></div>`:''}</section>
 ${done?`<button class="btn wide next" onclick="gramNext()">${s.i<n-1?'次へ →':'結果を見る'}</button>`:''}`}
function gramAnswer(k){const s=sess,q=s.qs[s.i];if(s.answered!==null)return;s.answered=k;s.total++;const r=gram(s.lid),miss=new Set(r.miss||[]);if(k===q.a){s.ok++;miss.delete(q.k)}else{s.missed.push(q);miss.add(q.k)}S.gram[s.lid]={...r,miss:[...miss]};save();speak(q.q.replace('___',q.choices[q.a]));render()}
function gramNext(){const s=sess;s.i++;s.answered=null;if(s.i>=s.qs.length){const r=gram(s.lid);S.gram[s.lid]={...r,best:s.full?Math.max(r.best,s.ok):r.best,tries:r.tries+1};save()}render();window.scrollTo(0,0)}
// ---- phrases ----
function phraseList(){return P.filter(p=>!ptheme||p.theme===ptheme)}
function phrases(){const themes=[...new Set(P.map(p=>p.theme))],xs=phraseList();
 return `<div class="page-head"><h1>フレーズ</h1><span class="muted">${themes.length}場面 · ${nf(P.length)}表現</span></div><div class="chips"><button class="chip" aria-pressed="${!ptheme}" onclick="ptheme='';render()">すべて</button>${themes.map(t=>`<button class="chip" aria-pressed="${ptheme===t}" onclick="ptheme='${t}';render()">${THEMES[t]||t}</button>`).join('')}</div>
 <section class="card practice"><div class="sec-head"><h2>一覧から練習</h2><span class="muted">10問ずつ</span></div><div class="pr-grid"><button class="pr dark" onclick="startQuiz('p',phraseList(),'jaen')"><b>日→英</b><small>日本語を見て<br>英語を選ぶ</small></button><button class="pr" onclick="startQuiz('p',phraseList(),'listen')"><b>聞き取り</b><small>音声を聞いて<br>意味を選ぶ</small></button></div></section>
 <p class="list-cap">表示 <b>${nf(xs.length)}</b>表現 · ${ptheme?esc(THEMES[ptheme]||ptheme):'すべて'}</p>
 <ul class="list wl">${xs.map(p=>`<li class="w-item"><button class="item" onclick="speak(${esc(JSON.stringify(p.en))})"><span class="w-head"><b>${esc(p.en)}</b></span><span class="w-ja">${esc(p.ja)}</span><span class="tags"><span class="t-theme">${esc(THEMES[p.theme]||p.theme)}</span>${p.note?`<span class="t-theme">· ${esc(p.note)}</span>`:''}</span></button><span class="w-acts">${audioBtn(p.en).replace('class="icon"','class="icon round"')}${starBtn(p.id)}</span></li>`).join('')}</ul>`}
// ---- review / favorites ----
function review(){const due=W.filter(w=>isDue(w.id)),seen=W.filter(w=>rec(w.id).seen>0),weak=seen.filter(w=>rec(w.id).ng>0).sort((a,b)=>rec(b.id).ng-rec(a.id).ng);
 return `<h1>復習</h1><section class="card"><h2>今日の復習</h2><p>${due.length?`${due.length}語が復習の時期です。`:'今は復習する語はありません。'}</p><button class="btn wide" ${due.length?'':'disabled'} onclick="startQuiz('w',due,'mix',true)">復習をはじめる →</button></section>
 <section class="card"><h2>間違えた語</h2>${weak.length?`<p class="muted">${weak.length}語</p><button class="btn light" onclick="startQuiz('w',weak,'mix',true)">間違えた語をやり直す</button>`:'<p class="muted">まだありません。</p>'}</section>
 ${(()=>{const rv=W.filter(w=>rec(w.id).rev);return `<section class="card"><h2>復習に登録した語</h2>${rv.length?`<p class="muted">${rv.length}語（復習で正解すると外れます）</p><div class="row-actions"><button class="btn light" onclick="startQuiz('w',W.filter(w=>rec(w.id).rev),'mix',true)">テスト</button><button class="btn light" onclick="startCards(W.filter(w=>rec(w.id).rev))">カード</button></div><ul class="list" style="margin-top:10px">${rv.slice(0,50).map(wordRow).join('')}</ul>`:'<p class="muted">単語のページの「復習」を押すと、ここに集まります。</p>'}</section>`})()}
 <section class="card"><h2>スピードゲーム</h2><p class="muted">60秒で英単語の意味を答えます。続けて正解するほど点が上がります。${S.games.speed?`ベスト ${S.games.speed}点`:''}</p><button class="btn" onclick="startGame()">はじめる →</button></section>
 <section class="card"><h2>学習した語から</h2><button class="btn light" ${seen.length>=4?'':'disabled'} onclick="startQuiz('w',seen,'mix',true)">ランダムに10問</button></section>`}
function favorites(){const fw=W.filter(w=>rec(w.id).fav),fp=P.filter(p=>rec(p.id).fav),xs=favTab==='w'?fw:fp;
 return `<h1>お気に入り</h1><div class="chips"><button class="chip" aria-pressed="${favTab==='w'}" onclick="favTab='w';render()">単語 ${fw.length}</button><button class="chip" aria-pressed="${favTab==='p'}" onclick="favTab='p';render()">フレーズ ${fp.length}</button></div>
 ${xs.length?`<div class="row-actions" style="margin-bottom:10px"><button class="btn light" onclick="startQuiz('${favTab}',${favTab==='w'?'W':'P'}.filter(x=>rec(x.id).fav),'${favTab==='w'?'enja':'jaen'}')">お気に入りでテスト</button></div><ul class="list">${xs.map(x=>favTab==='w'?`<li><button class="item" onclick="openWord('${x.id}')"><b>${esc(x.w)}</b><small>${esc(x.ja)}</small></button>${audioBtn(x.w)}${starBtn(x.id)}</li>`:`<li><button class="item" onclick="speak(${esc(JSON.stringify(x.en))})"><b>${esc(x.en)}</b><small>${esc(x.ja)}</small></button>${audioBtn(x.en)}${starBtn(x.id)}</li>`).join('')}</ul>`:'<div class="empty">☆ を押すとここに集まります。</div>'}`}
function settings(){return `<h1>設定</h1><section class="card settings"><label>音声の速さ<select onchange="S.rate=Number(this.value);save()">${[[0.7,'ゆっくり'],[0.8,'やや遅め'],[0.9,'ふつう'],[1,'速め']].map(([v,t])=>`<option value="${v}" ${S.rate===v?'selected':''}>${t}</option>`).join('')}</select></label>${stepSettings()}</section>
 <section class="card"><h2>学習データ</h2><p class="muted">学習記録はこの端末のブラウザに保存されます。書き出して別の端末で読み込めます。</p><div class="row-actions"><button class="btn light" onclick="exportData()">書き出す</button><label class="btn light">読み込む<input type="file" accept="application/json" hidden onchange="importData(this.files[0])"></label></div></section>
`}
function exportData(){const b=new Blob([JSON.stringify({app:KEY,version:1,state:S},null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='english-steps-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function importData(f){if(!f)return;f.text().then(t=>{const v=JSON.parse(t);if(v.app!==KEY)throw Error();S=sanitize(v.state);save();toast('読み込みました');render()}).catch(()=>toast('読み込めませんでした'))}
// ---- sessions ----
// task: {type:'learn'|'enja'|'jaen'|'listen', id, kind:'w'|'p'}
function startStep(pool){const base=pool||mainW(),news=nextWords(base),due=shuffle(base.filter(w=>isDue(w.id))).slice(0,10),tasks=[];
 news.forEach(w=>tasks.push({type:'learn',id:w.id,kind:'w'}));shuffle(news).forEach(w=>tasks.push({type:'enja',id:w.id,kind:'w'}));shuffle(news).forEach(w=>tasks.push({type:'jaen',id:w.id,kind:'w'}));due.forEach(w=>tasks.push({type:'enja',id:w.id,kind:'w'}));
 if(!tasks.length){toast('学習する語がありません');return}sess={kind:'step',tasks,i:0,ok:0,total:0,answered:null,missed:new Set(),news:news.map(w=>w.id)};render();window.scrollTo(0,0);autoSpeak()}
function startQuiz(kind,pool,mode,srs=false){const ok=kind==='p'?pool:pool;if(ok.length<2){toast('問題を作れる語が足りません');return}const pick=shuffle(ok).slice(0,10),tasks=pick.map(x=>({type:mode==='mix'?['enja','jaen','listen'][Math.floor(Math.random()*3)]:mode,id:x.id,kind}));
 sess={kind:'quiz',srs,tasks,i:0,ok:0,total:0,answered:null,missed:new Set()};render();window.scrollTo(0,0);autoSpeak()}
const item=t=>t.kind==='w'?byId.get(t.id):byId.get(t.id);
const en=x=>x.w||x.en;
function choicesFor(t){const x=item(t),pool=(t.kind==='w'?W:P).filter(y=>y.id!==x.id),others=shuffle(pool.filter(y=>(t.kind!=='w'||y.pos===x.pos))).slice(0,3);while(others.length<3){const y=shuffle(pool).find(y=>!others.includes(y));if(!y)break;others.push(y)}return shuffle([x,...others])}
function autoSpeak(){const t=sess&&sess.tasks&&sess.tasks[sess.i];if(!t||!S.autoplay)return;const x=item(t);if(t.type==='learn'||t.type==='listen'||t.type==='enja')setTimeout(()=>speak(en(x)),200)}
function sessionView(){const s=sess,n=s.tasks.length;if(s.i>=n)return resultView();const t=s.tasks[s.i],x=item(t);
 const top=`<div class="sess-top"><button class="btn light" style="min-height:40px" onclick="endSession()">← 終了</button><span class="muted">${s.i+1} / ${n}</span></div><div class="progress"><i style="width:${s.i/n*100}%"></i></div>`;
 if(t.type==='learn')return top+`<section class="card"><p class="muted">新しい語</p><div style="display:flex;justify-content:space-between;gap:8px"><div><p class="word-big">${esc(x.w)}</p><span class="ipa-big">/${esc(x.ipa)}/</span> <span class="pos">${esc(x.pos)}</span></div>${audioBtn(x.w)}</div><p class="ja-big">${esc(x.ja)}</p><div class="ex"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><p class="en">${exWords(x.ex,'speak',x.id)}</p>${audioBtn(x.ex,'例文を再生')}</div><p>${esc(x.exJa)}</p></div></section><button class="btn wide next" onclick="nextTask()">覚えた → 次へ</button>`;
 if(!s.choices||s.choicesFor!==s.i){s.choices=choicesFor(t);s.choicesFor=s.i}
 const label=c=>t.type==='jaen'?en(c):c.ja,done=s.answered!==null;
 const prompt=t.type==='enja'?`<div class="q-prompt"><div class="big">${esc(en(x))}</div>${x.ipa?`<div class="sub">/${esc(x.ipa)}/</div>`:''}<button class="icon" style="margin:8px auto 0" onclick="speak(${esc(JSON.stringify(en(x)))})" aria-label="発音">${icon('audio')}</button><div class="sub">意味は？</div></div>`:t.type==='jaen'?`<div class="q-prompt"><div class="big" style="font-size:1.5rem">${esc(x.ja)}</div><div class="sub">英語は？</div></div>`:`<div class="q-prompt"><button class="play" onclick="speak(${esc(JSON.stringify(en(x)))})" aria-label="もう一度聞く">${icon('audio')}</button><div class="sub">聞こえた英語の意味は？</div></div>`;
 return top+`<section class="card">${prompt}<div class="choices">${s.choices.map((c,k)=>`<button class="choice${done?(c.id===x.id?' ok':k===s.answered?' ng':''):''}" ${done?'disabled':''} onclick="answer(${k})">${esc(label(c))}${done&&t.type!=='jaen'?` <span class="muted">${esc(en(c))}</span>`:''}</button>`).join('')}</div>${done?`<div class="ex" style="margin-top:12px"><p class="en">${esc(en(x))} ${x.ipa?`<span class="muted">/${esc(x.ipa)}/</span>`:''}</p><p>${esc(x.ja)}</p>${x.ex?`<p class="muted" style="margin-top:6px">${esc(x.ex)} — ${esc(x.exJa)}</p>`:''}</div>`:''}</section>${done?`<button class="btn wide next" onclick="nextTask()">${s.i<n-1?'次へ →':'結果を見る'}</button>`:''}`}
function answer(k){const s=sess,t=s.tasks[s.i],x=item(t);if(s.answered!==null)return;s.answered=k;const ok=s.choices[k].id===x.id;s.total++;if(ok)s.ok++;else{s.missed.add(x.id);if(s.kind==='step'&&!s.tasks.slice(s.i+1).some(u=>u.id===x.id&&u.type===t.type))s.tasks.push({...t})}
 if(t.kind==='w'||t.kind==='p'){const r=rec(x.id);if(s.kind==='quiz'&&!s.srs){setRec(x.id,{seen:Math.max(1,r.seen),ok:r.ok+(ok?1:0),ng:r.ng+(ok?0:1)})}else if(!(s.kind==='step'&&s.news.includes(x.id))){const st=ok?Math.min(6,(r.stage||0)+1):0;setRec(x.id,{rev:ok?false:r.rev,seen:r.seen+1,stage:st,due:ok?Date.now()+DAYS[st-1]*86400000:Date.now(),ok:r.ok+(ok?1:0),ng:r.ng+(ok?0:1)})}else setRec(x.id,{ok:r.ok+(ok?1:0),ng:r.ng+(ok?0:1)})}
 speak(en(x));render()}
function nextTask(){const s=sess;s.i++;s.answered=null;s.choices=null;if(s.i>=s.tasks.length)finishSession();render();window.scrollTo(0,0);autoSpeak()}
function finishSession(){const s=sess;if(s.kind!=='step'||s.finished)return;s.finished=true;const now=Date.now();
 for(const id of s.news){const r=rec(id),miss=s.missed.has(id);setRec(id,{seen:r.seen+1,stage:miss?0:1,due:miss?now:now+DAYS[0]*86400000})}
 const d=today();S.today=S.today.date===d?{date:d,steps:S.today.steps+1}:{date:d,steps:1};if(S.streak.last!==d)S.streak={last:d,days:S.streak.last===yesterday()?S.streak.days+1:1};save()}
function resultView(){const s=sess;return `<section class="card result"><p class="muted">${s.kind==='step'?'ステップ完了':'テスト結果'}</p><div class="score">${s.ok} / ${s.total}</div><p>${s.ok===s.total?'全問正解です！':'間違えた語は復習に残ります。'}</p><div class="row-actions" style="justify-content:center">${s.missed.size?`<button class="btn" onclick="startQuiz('w',[...sess.missed].map(id=>byId.get(id)).filter(x=>x&&x.w),'enja',true)">間違えた語をもう一度</button>`:''}<button class="btn light" onclick="endSession()">戻る</button></div></section>`}
function endSession(){if(sess&&sess.kind==='step'&&sess.i>=sess.tasks.length)finishSession();sess=null;render();window.scrollTo(0,0)}
// ---- boot ----
load();
Promise.all(['data/words.json','data/phrases.json','data/grammar.json'].map(u=>fetch(u+'?v=20261116k').then(r=>{if(!r.ok)throw Error();return r.json()}))).then(([w,p,g])=>{W=w;P=p;G=g;byId=new Map([...W,...P].map(x=>[x.id,x]));loadState='ready';render();fetch('data/ja-readings.json?v=20261116k').then(r=>r.ok?r.json():{}).then(x=>{R=x&&typeof x==='object'?x:{};if(view==='dict')render()}).catch(()=>{})}).catch(()=>{loadState='error';render()});
if(typeof navigator!=='undefined'&&'serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('sw.js',{scope:'./'}).catch(()=>{});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['home','dict','words','grammar','phrases','review','favorites','settings'].includes(v))go(v)});
render();
if(typeof module!=='undefined')module.exports={};
